import { useEffect, useState } from "react";

/**
 * Fetches a full lookup list (departments, courses, students, etc.) once,
 * for populating <select> options. Keeps a generous limit since these
 * dropdowns are meant to show the whole list, not a paginated slice.
 */
export function useLookupOptions(fetchAllFn, mapFn, deps = []) {
  const [options, setOptions] = useState([]);
  const [isLoading, setIsLoading] = useState(true);

  useEffect(() => {
    let isCurrent = true;
    setIsLoading(true);
    fetchAllFn({ limit: 500 })
      .then(({ data }) => {
        if (!isCurrent) return;
        const list = Array.isArray(data) ? data : data?.data || data?.items || [];
        setOptions(list.map(mapFn));
      })
      .catch(() => {
        if (isCurrent) setOptions([]);
      })
      .finally(() => {
        if (isCurrent) setIsLoading(false);
      });
    return () => {
      isCurrent = false;
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, deps);

  return { options, isLoading };
}
